import {catalog,torque,cost,engineForHp,peakPower,HP_TO_KW} from './physics.mjs';
const money=n=>n.toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0});
const mass=b=>1120+b.engine.mass+b.weight.mass+b.aero.mass;
const lessons={
 engine:{title:'Engine: where does the power live?',idea:'Torque is the engine’s twisting force. Gears turn that twist into force at the tires. Power describes how quickly the engine can do work, so both torque and RPM matter.',formula:'Power (kW) = torque (N·m) × RPM × 2π ÷ 60,000',trade:'Choose 120–300 hp. In this engine family, higher output needs more expensive, heavier hardware and shifts the power band upward. Torque falls off near the rev limit, so holding a gear too long can lose time. These are modeled upgrade packages, not a universal horsepower-to-weight rule.',question:'After an upshift, will the engine land in a strong part of its torque curve?',axis:'Engine speed (RPM)',range:[1000,7000,250],start:4000},
 tires:{title:'Tires: turn torque into traction.',idea:'The road pushes the car forward through friction. The tires can only transmit so much force before grip becomes the limit. A larger friction coefficient (μ) increases that limit.',formula:'Maximum tire force = μ × normal force on the driven tires',trade:'More grip helps a powerful launch. These grippier packages also have more rolling resistance, which resists motion throughout the race. Grip is useful only when you need it.',question:'Does your engine ask for more driving force than the tires can transmit?',axis:'Rear-tire normal force (N)',range:[2000,10000,250],start:6000},
 weight:{title:'Mass: how much car must you accelerate?',idea:'The same net force accelerates a lighter car more quickly. Net force means driving force after subtracting air drag and rolling resistance.',formula:'Acceleration (m/s²) = net force (N) ÷ mass (kg)',trade:'Lightweight parts cost money for relatively small mass savings. During a grip-limited launch, reducing mass also reduces tire loading, so acceleration does not improve as much as a fixed-force example suggests.',question:'Is a small mass saving worth more than another use of the same budget?',axis:'Net force (N)',range:[0,8000,250],start:4000},
 aero:{title:'Aerodynamics: the cost of pushing air.',idea:'Drag increases with speed squared. Doubling speed produces four times the aerodynamic drag. CdA combines body shape and frontal area: lower is better for a straight-line run.',formula:'Air drag (N) = ½ × air density × CdA × speed²',trade:'The underbody packages reduce drag but add mass. They help most near the fast end of the course; at launch there is almost no aerodynamic drag to remove.',question:'Will the car spend enough of this short race at high speed to justify this purchase?',axis:'Road speed (km/h)',range:[0,200,5],start:160},
 gearing:{title:'Gearing: trade wheel force for road speed.',idea:'A larger final-drive ratio multiplies engine torque more. But the engine must turn faster at the same road speed, so you reach the shift point sooner.',formula:'Wheel force = torque × gear ratio × final drive × efficiency ÷ tire radius',trade:'Short gearing can help acceleration but may add a shift. Tall gearing gives more speed per RPM but less wheel force. Gears redistribute power; they do not create it.',question:'Will stronger wheel force outweigh the time spent making an extra shift?',axis:'Engine speed in first gear (RPM)',range:[1000,7000,250],start:4000},
 shifter:{title:'Shifting: acceleration takes a break.',idea:'While the driver changes gears, this model temporarily applies no engine driving force. Air drag and rolling resistance still act, so the car slows slightly.',formula:'Total time without engine drive = number of shifts × shift duration',trade:'The short-throw package reduces each interruption by 0.10 s. Saving interruption time does not translate one-for-one into finish-time savings; it depends on when each shift happens.',question:'Does your gearing require enough shifts to make this upgrade worthwhile?',axis:'Number of gear changes',range:[0,5,1],start:3}
};
function series(k,b){const p=b[k],e=b.engine;
 switch(k){
 case 'engine':return [{title:'Engine torque',unit:'N·m',fn:r=>torque(e,r)},{title:'Engine power',unit:'kW',fn:r=>torque(e,r)*r*2*Math.PI/60000}];
 case 'tires':return [{title:'Grip limit at the rear tires',unit:'N',fn:n=>p.mu*n}];
 case 'weight':return [{title:'Acceleration at the same net force',unit:'m/s²',fn:f=>f/mass(b)}];
 case 'aero':return [{title:'Aerodynamic drag',unit:'N',fn:v=>.5*1.225*p.cda*(v/3.6)**2}];
 case 'gearing':return [{title:'Available first-gear wheel force, before the grip limit',unit:'N',fn:r=>torque(e,r)*3.14*p.ratio*.88/.29}];
 case 'shifter':return [{title:'Total interruption of engine drive',unit:'s',fn:n=>p.delay*n}];
 }
}
const fmt=n=>Number.isInteger(n)?n.toLocaleString():n.toLocaleString(undefined,{maximumFractionDigits:2});
function graph(a,b,lesson,probe){
 const [lo,hi]=lesson.range,n=60,values=Array.from({length:n+1},(_,i)=>lo+(hi-lo)*i/n),rawMax=Math.max(1,...values.flatMap(v=>[a.fn(v),b.fn(v)]))*1.1,step=10**Math.floor(Math.log10(rawMax/4)),max=Math.ceil(rawMax/4/step)*step*4;
 const x=v=>62+(v-lo)/(hi-lo)*500,y=v=>177-v/max*145;
 const line=s=>values.map(v=>`${x(v)},${y(s.fn(v))}`).join(' ');
 return `<figure class="lab-chart"><figcaption>${b.title} <span>(${b.unit})</span></figcaption><svg viewBox="0 0 610 235" role="img" aria-label="${b.title}: installed package dashed, preview solid"><title>${b.title}. X axis: ${lesson.axis}. Y axis: ${b.unit}.</title>${[0,.25,.5,.75,1].map(f=>`<path d="M62 ${y(max*f)}H562" stroke="#3b4947"/><text x="54" y="${y(max*f)+4}" text-anchor="end" fill="#b4c1bb" font-size="16">${fmt(max*f)}</text>`).join('')}${[0,.25,.5,.75,1].map(f=>`<text x="${x(lo+(hi-lo)*f)}" y="198" text-anchor="middle" fill="#b4c1bb" font-size="16">${fmt(lo+(hi-lo)*f)}</text>`).join('')}<polyline points="${line(a)}" fill="none" stroke="#ffb77b" stroke-dasharray="7 5" stroke-width="3"/><polyline points="${line(b)}" fill="none" stroke="#c4f46f" stroke-width="3"/><path d="M${x(probe)} 25V177" stroke="#87ccd2" stroke-dasharray="3 4"/><circle cx="${x(probe)}" cy="${y(b.fn(probe))}" r="5" fill="#c4f46f"/><text x="310" y="225" text-anchor="middle" fill="#c3cec7" font-size="16">${lesson.axis}</text></svg></figure>`;
}
export function mountUpgradeLab({getBuild,getSelection,apply,names,labels,descriptions}){
 const dialog=document.createElement('dialog');dialog.id='upgrade-dialog';dialog.className='upgrade-dialog';document.body.append(dialog);
 let key,choice,probe;
 function draw(){
  const lesson=lessons[key],current=getBuild(),candidate={...current,[key]:choice},a=series(key,current),b=series(key,candidate),delta=cost(candidate)-cost(current),remaining=8000-cost(candidate);
  dialog.innerHTML=`<div class="dialog-top"><p class="eyebrow">GARAGE / PHYSICS WORKSHOP</p><button class="quiet" id="lab-close">Cancel</button></div><h2 id="lab-title">${lesson.title}</h2><div class="lab-explain"><p>${lesson.idea}</p><div class="lab-formula">${lesson.formula}</div><p><b>The trade-off:</b> ${lesson.trade}</p></div>${key==='engine'?engineControls(current):`<h3>Choose a package to compare</h3><div class="lab-options">${catalog[key].map((p,i)=>`<button class="lab-option ${choice.id===p.id?'chosen':''}" aria-pressed="${choice.id===p.id}" data-part="${p.id}"><span>${labels[key][i]}</span><b>${p.cost?money(p.cost):'Included'}</b><small>${descriptions[key][i]}</small>${getSelection()[key]===p.id?'<em>INSTALLED</em>':''}</button>`).join('')}</div>`}<div class="lab-comparison"><div class="lab-chart-legend"><span>– – Installed package</span><span>━━ Preview package</span></div><div class="lab-graphs">${b.map((s,i)=>graph(a[i],s,lesson,probe)).join('')}</div><label class="lab-probe-label" for="lab-probe">Explore: ${lesson.axis} <output id="lab-probe-value">${fmt(probe)}</output></label><input id="lab-probe" type="range" min="${lesson.range[0]}" max="${lesson.range[1]}" step="${lesson.range[2]}" value="${probe}"><table class="lab-table"><thead><tr><th>At this setting</th><th>Installed</th><th>Preview</th><th>Change</th></tr></thead><tbody id="lab-values">${metrics(a,b,current,candidate)}</tbody></table><p class="lab-assumption">${key==='tires'?'The slider sets rear-tire normal force; the race also models weight transfer.':key==='weight'?'Other forces are held fixed here to isolate mass. Actual race forces change with speed and grip.':key==='gearing'?'First gear = 3.14; efficiency = 88%; tire radius = 0.29 m. Actual force is capped by tire grip.':key==='aero'?'Air density = 1.225 kg/m³. The graph shows air drag only, not rolling resistance.':'Other installed parts remain fixed in this comparison.'} Curves and parameters are those used by this classroom simulation, not measured dyno data.</p></div><p class="lab-question">Think before buying: ${lesson.question}</p><div class="lab-buy"><div id="lab-budget"><strong>${delta===0?'No change in cost':`${delta>0?'+':'−'}${money(Math.abs(delta))} versus installed`}</strong><span class="${remaining<0?'budget-warning':''}">${money(remaining)} remaining after this choice${remaining<0?' — swap other parts before racing':''}</span></div><button class="primary" id="lab-apply">${choice.id===current[key].id?'KEEP PACKAGE':'INSTALL PACKAGE'}</button></div>`;
  dialog.setAttribute('aria-labelledby','lab-title');
  dialog.querySelector('#lab-close').onclick=()=>dialog.close();
  dialog.querySelectorAll('[data-part]').forEach(button=>button.onclick=()=>{choice=catalog[key].find(p=>p.id===button.dataset.part);const scroll=dialog.scrollTop;draw();dialog.scrollTop=scroll;dialog.querySelector(`[data-part="${choice.id}"]`).focus({preventScroll:true});});
  if(key==='engine'){
    const update=()=>{
      const current=getBuild(),candidate={...current,engine:choice},a=series(key,current),b=series(key,candidate),delta=cost(candidate)-cost(current),remaining=8000-cost(candidate);
      dialog.querySelector('#engine-hp-label').textContent=`${choice.hp} hp`;
      dialog.querySelector('#engine-specs').innerHTML=engineSpecs(candidate);
      dialog.querySelector('.lab-graphs').innerHTML=b.map((s,i)=>graph(a[i],s,lessons[key],probe)).join('');
      dialog.querySelector('#lab-values').innerHTML=metrics(a,b,current,candidate);
      dialog.querySelector('#lab-budget').innerHTML=`<strong>${delta===0?'No change in cost':`${delta>0?'+':'−'}${money(Math.abs(delta))} versus installed`}</strong><span class="${remaining<0?'budget-warning':''}">${money(remaining)} remaining${remaining<0?' — swap other parts before racing':''}</span>`;
      dialog.querySelector('#lab-apply').textContent=choice.id===current.engine.id?'KEEP ENGINE':'INSTALL ENGINE';
      dialog.querySelectorAll('[data-hp]').forEach(p=>p.setAttribute('aria-pressed',String(Number(p.dataset.hp)===choice.hp)));
    };
    dialog.querySelector('#engine-hp').oninput=e=>{choice=engineForHp(Number(e.target.value));update();};
    dialog.querySelectorAll('[data-hp]').forEach(p=>p.onclick=()=>{choice=engineForHp(Number(p.dataset.hp));dialog.querySelector('#engine-hp').value=choice.hp;update();});
  }
  dialog.querySelector('#lab-apply').onclick=()=>{apply(key,choice.id);dialog.close();};
  dialog.querySelector('#lab-probe').oninput=e=>{probe=Number(e.target.value);const current=getBuild(),candidate={...current,[key]:choice},a=series(key,current),b=series(key,candidate);dialog.querySelector('#lab-probe-value').textContent=fmt(probe);dialog.querySelector('.lab-graphs').innerHTML=b.map((s,i)=>graph(a[i],s,lesson,probe)).join('');dialog.querySelector('#lab-values').innerHTML=metrics(a,b,current,candidate);};
 }
 function engineSpecs(build){
  const e=build.engine,next=engineForHp(Math.min(300,e.hp+10));
  return `<div><span>ENGINE PRICE</span><strong>${money(e.cost)}</strong></div><div><span>ADDED HARDWARE</span><strong>+${fmt(e.mass)} kg</strong></div><div><span>BUILD POWER / WEIGHT</span><strong>${fmt(peakPower(e)/(mass(build)/1000))} kW/t</strong></div><p>${e.hp<300?`Next ${next.hp-e.hp} hp: +${money(next.cost-e.cost)} and +${fmt(next.mass-e.mass)} kg. What else could that money buy?`:'Maximum output leaves little money for grip and other upgrades.'}</p>`;
 }
 function engineControls(current){return `<h3>Choose peak engine horsepower</h3><div class="engine-tuner"><label for="engine-hp">Engine output <output id="engine-hp-label">${choice.hp} hp</output></label><input id="engine-hp" type="range" min="120" max="300" step="1" value="${choice.hp}"><div class="range-labels"><span>120 hp · stock</span><span>300 hp · high output</span></div><div class="engine-presets">${[120,180,240,300].map(h=>`<button class="quiet" data-hp="${h}" aria-pressed="${h===choice.hp}">${h} hp</button>`).join('')}</div><div id="engine-specs">${engineSpecs({...current,engine:choice})}</div></div>`;}
 function metrics(a,b,current,candidate){
  const rows=a.map((s,i)=>[s.title+` (${s.unit})`,s.fn(probe),b[i].fn(probe)]);
  if(key==='engine')rows.push(['Peak engine power (hp)',peakPower(current.engine)/HP_TO_KW,peakPower(candidate.engine)/HP_TO_KW],['Engine cost ($)',current.engine.cost,candidate.engine.cost]);
  if(key==='engine'||key==='weight'||key==='aero')rows.push(['Total car mass (kg)',mass(current),mass(candidate)]);
  if(key==='tires')rows.push(['Friction coefficient μ',current.tires.mu,candidate.tires.mu],['Rolling resistance (N)',current.tires.crr*mass(current)*9.81,candidate.tires.crr*mass(candidate)*9.81]);
  if(key==='gearing')rows.push(['Road speed in first gear (km/h)',probe/(3.14*current.gearing.ratio)*2*Math.PI*.29/60*3.6,probe/(3.14*candidate.gearing.ratio)*2*Math.PI*.29/60*3.6]);
  return rows.map(([label,a,b])=>`<tr><th>${label}</th><td>${fmt(a)}</td><td>${fmt(b)}</td><td>${b-a>0?'+':''}${fmt(b-a)}</td></tr>`).join('');
 }
 return k=>{key=k;choice=getBuild()[key];probe=lessons[key].start;draw();dialog.showModal();dialog.scrollTop=0;};
}
